109	// ledgerFlagSet 构造 -l/--ledger、-f/--file 标志。
110	func ledgerFlagSet(name string) (*flag.FlagSet, *string, *string) {
111		fs := flag.NewFlagSet(name, flag.ContinueOnError)
112		fs.SetOutput(io.Discard)
113		var ledgerPath, inputFile string
114		fs.StringVar(&ledgerPath, "ledger", "", "ledger file path")
115		fs.StringVar(&ledgerPath, "l", "", "ledger file path (shorthand)")
116		fs.StringVar(&inputFile, "file", "", "JSON input file (default stdin)")
117		fs.StringVar(&inputFile, "f", "", "JSON input file (shorthand)")
118		return fs, &ledgerPath, &inputFile
119	}
