252	func cmdReconcile(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
253		fs, ledgerPath, inputFile := ledgerFlagSet("reconcile")
254		// 序号边界：after 排除下界、through 包含上界（after < seq <= through）。
255		// 用指针区分“未提供”与显式给出的 0：未提供时由库取缺省值（下界 0、
256		// 上界为该类记录的最大成功序号）。
257		var paymentAfter, paymentThrough, refundAfter, refundThrough int64
258		fs.Int64Var(&paymentAfter, "payment-after", 0, "payment seq lower bound (exclusive)")
259		fs.Int64Var(&paymentThrough, "payment-through", 0, "payment seq upper bound (inclusive)")
260		fs.Int64Var(&refundAfter, "refund-after", 0, "refund seq lower bound (exclusive)")
261		fs.Int64Var(&refundThrough, "refund-through", 0, "refund seq upper bound (inclusive)")
262		if err := fs.Parse(args); err != nil {
263			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
264		}
265		if *ledgerPath == "" {
266			return failEnvelope(stderr, payflow.ErrInvalid, "reconcile requires --ledger <path>")
267		}
268		raw, err := readInput(*inputFile, stdin)
269		if err != nil {
270			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
271		}
272		// 先严格解析全部输入：任一条目不合法则整次拒绝，退出码 1，不输出部分报告。
273		entries, err := payflow.ParseReconcileRequest(raw)
274		if err != nil {
275			return failWithError(stderr, err)
276		}
277	
278		bounds := payflow.ReconcileBounds{}
279		fs.Visit(func(f *flag.Flag) {
280			switch f.Name {
281			case "payment-after":
282				v := paymentAfter
283				bounds.PaymentAfter = &v
284			case "payment-through":
285				v := paymentThrough
286				bounds.PaymentThrough = &v
287			case "refund-after":
288				v := refundAfter
289				bounds.RefundAfter = &v
290			case "refund-through":
291				v := refundThrough
292				bounds.RefundThrough = &v
293			}
294		})
295	
296		l, err := payflow.Open(*ledgerPath)
297		if err != nil {
298			return failWithError(stderr, err)
299		}
